<script setup lang="ts">
import {computed,ref} from 'vue';import {useCart} from '../stores/cart';import {useLanguage} from '../stores/language'
const cart=useCart(),language=useLanguage(),open=ref(false),name=ref(''),phone=ref(''),email=ref(''),address=ref(''),pincode=ref(''),consent=ref(false),busy=ref(false),error=ref('');const ar=computed(()=>language.locale==='ar')
const paymentDone=ref(false),paymentId=ref('');const checkoutEnabled=import.meta.env.VITE_CHECKOUT_ENABLED==='true';type RazorpayResult={razorpay_order_id:string;razorpay_payment_id:string;razorpay_signature:string};type RazorpayConstructor=new (options:Record<string,unknown>)=>{open:()=>void};declare global {interface Window { Razorpay?:RazorpayConstructor }};function loadCheckout(){return new Promise<void>((resolve,reject)=>{if(window.Razorpay){resolve();return}const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=()=>resolve();script.onerror=()=>reject(new Error('Could not load secure checkout'));document.head.appendChild(script)})};const message=computed(()=>`Hello Noor Al Zahra, my name is ${name.value || '[name]'}. I would like to enquire about: ${cart.items.map(i=>`${i.name} × ${i.quantity}`).join(', ')}. Please confirm price and delivery.${paymentId.value?' Payment confirmed: '+paymentId.value:''}`)
async function pay(){error.value='';busy.value=true;try{const response=await fetch('/api/order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.value,phone:phone.value,email:email.value,address:address.value,pincode:pincode.value,items:cart.items.map(i=>({id:i.name.toLowerCase().replaceAll(' ','-'),quantity:i.quantity})),consent:consent.value,website:''})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Online payments are not configured yet.');await loadCheckout();if(!window.Razorpay)throw new Error('Could not load secure checkout');const checkout=new window.Razorpay({key:data.key,order_id:data.id,amount:data.amount,currency:data.currency,name:'Noor Al Zahra',prefill:{name:name.value,email:email.value,contact:phone.value},handler:async(result:RazorpayResult)=>{try{const verification=await fetch('/api/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(result)});if(!verification.ok)throw new Error('Payment confirmation is pending. Please contact us with your payment ID.');paymentDone.value=true;paymentId.value=result.razorpay_payment_id}catch(e){error.value=e instanceof Error?e.message:'Verification failed'}}});checkout.open()}catch(e){error.value=e instanceof Error?e.message:'Please try again.'}finally{busy.value=false}}
</script>
<template><div><button class="cart-open" @click="open=true" :aria-label="$t('cart')">{{ar?'اختياراتي':'SELECTION'}} ({{cart.count}})</button><div v-if="open" class="cart-backdrop" @click.self="open=false"><aside class="cart-panel" role="dialog" aria-modal="true" :aria-label="$t('cart')"><div class="cart-title"><h2>{{$t('cart')}}</h2><button @click="open=false" aria-label="Close">×</button></div><p v-if="!cart.count">{{$t('empty')}}</p><template v-else><div v-for="item in cart.items" :key="item.name" class="cart-row"><span>{{item.name}} × {{item.quantity}}</span><button @click="cart.remove(item.name)">{{ar?'إزالة':'Remove'}}</button></div><p class="muted">{{ar?'سيتم تأكيد السعر والتوصيل عند الطلب.':'Prices and delivery are confirmed on enquiry.'}}</p><form @submit.prevent="pay"><label>{{ar?'الاسم':'Name'}}<input v-model="name" required autocomplete="name"></label><label>{{ar?'الهاتف':'Phone'}}<input v-model="phone" required autocomplete="tel"></label><label>{{ar?'البريد الإلكتروني':'Email'}}<input v-model="email" required type="email" autocomplete="email"></label><label>{{ar?'العنوان':'Address'}}<input v-model="address" required autocomplete="street-address"></label><label>{{ar?'الرمز البريدي':'Postal code'}}<input v-model="pincode" required autocomplete="postal-code"></label><label class="check"><input v-model="consent" type="checkbox" required> {{ar?'أوافق على استخدام بياناتي لمعالجة طلبي.':'I agree to the use of my details to process this request.'}}</label><p class="muted">{{ar?'الدفع الإلكتروني غير متاح حتى تأكيد المنتجات والأسعار.':'Online payment will be available after products and prices are confirmed.'}}</p><button class="button outline" :disabled="busy||!checkoutEnabled">{{ar?'الدفع عبر الإنترنت':'PAY ONLINE'}}</button><p v-if="error" role="alert">{{error}}</p><p v-if="paymentDone" role="status">{{ar?'تم تأكيد الدفع.':'Payment confirmed. You may send us a WhatsApp confirmation below.'}}</p></form><a class="button gold" target="_blank" rel="noopener" :href="'https://wa.me/916361946903?text='+encodeURIComponent(message)">{{$t('checkout')}}</a><button class="text-button" @click="cart.clear()">{{$t('clear')}}</button></template></aside></div></div></template>
